using Microsoft.Extensions.Logging;

namespace Pmad.AI.LlamaSharp;

/// <summary>
/// Delegate that allows custom normalization of function names and arguments parsed from local model responses.
/// </summary>
/// <param name="name">The raw function name generated by the model.</param>
/// <param name="arguments">The parsed arguments dictionary.</param>
/// <returns>A tuple with normalized name and arguments, or null to keep them unchanged.</returns>
public delegate (string Name, IDictionary<string, object?> Arguments)? FunctionCallNormalizer(string name, IDictionary<string, object?> arguments);

/// <summary>
/// Configuration options for <see cref="LlamaSharpChatClient"/>.
/// For resilient tool call healing, compaction, and argument repair pipelines, wrap the resulting client
/// with <c>UseRecommendedSlmPipeline</c> from <c>Pmad.AI</c>.
/// </summary>
public sealed class LlamaSharpOptions
{
    /// <summary>
    /// Explicit absolute path to a local .gguf model file.
    /// </summary>
    public string? ModelPath { get; set; }

    /// <summary>
    /// Optional root directory where downloaded GGUF models are cached.
    /// </summary>
    public string? ModelsDirectory { get; set; }

    /// <summary>
    /// Explicit absolute path to a multimodal projector (<c>mmproj-*.gguf</c>) file for vision support.
    /// </summary>
    public string? MmprojPath { get; set; }

    /// <summary>
    /// Explicit absolute path to a Multi-Token Prediction (MTP) draft model (<c>mtp-*.gguf</c>) file for speculative decoding acceleration.
    /// </summary>
    public string? MtpPath { get; set; }

    /// <summary>
    /// Context window size (in tokens) to allocate for model execution.
    /// Default is 49152 tokens (48k), supporting long-context agent scenarios.
    /// </summary>
    public int ContextSize { get; set; } = 49152;

    /// <summary>
    /// Number of model layers to offload to GPU via the active hardware backend.
    /// Defaults to 99 (full GPU offload). Set to 0 to force CPU execution.
    /// </summary>
    public int GpuLayerCount { get; set; } = 99;

    /// <summary>
    /// Number of CPU threads to allocate for model generation/inference.
    /// When null, LLamaSharp / llama.cpp default thread heuristics are used.
    /// </summary>
    public int? Threads { get; set; }

    /// <summary>
    /// Number of CPU threads to allocate for prompt batch processing.
    /// When null, defaults to <see cref="Threads"/> or LLamaSharp defaults.
    /// </summary>
    public int? BatchThreads { get; set; }

    /// <summary>
    /// Evaluation batch size in tokens. Defaults to 2048.
    /// </summary>
    public uint BatchSize { get; set; } = 2048;

    /// <summary>
    /// Chat prompt template format (e.g. "chatml", "gemma4", "phi3"). Defaults to "chatml".
    /// </summary>
    public string PromptFormat { get; set; } = "chatml";

    /// <summary>
    /// Optional custom token estimator used for prompt budget estimation and safe token counting.
    /// When null, an estimator matched to the active preset or dialect is used, falling back to <see cref="Pmad.AI.Tokens.HeuristicTokenEstimator.Default"/>.
    /// </summary>
    public Pmad.AI.Tokens.HeuristicTokenEstimator? TokenEstimator { get; set; }

    /// <summary>
    /// Safety margin percentage applied when prompt tokens are estimated heuristically
    /// by <see cref="LlamaSharpChatClient.SafeCountInputTokens"/> (for large prompts > 7 KB or tokenizer fallbacks).
    /// Defaults to 0.05 (+5% headroom). Set to 0.0 to disable the margin.
    /// </summary>
    public double EstimatedTokenSafetyMargin { get; set; } = 0.05;

    /// <summary>
    /// Optional chat prompt template dialect. When specified, overrides <see cref="PromptFormat"/>.
    /// </summary>
    public ChatDialect? Dialect { get; set; }

    /// <summary>
    /// Default sampling temperature. Defaults to 0.7.
    /// </summary>
    public float DefaultTemperature { get; set; } = 0.7f;

    /// <summary>
    /// Default maximum output tokens if not specified in ChatOptions. Defaults to 2048.
    /// </summary>
    public int DefaultMaxOutputTokens { get; set; } = 2048;

    /// <summary>
    /// Controls whether internal reasoning / chain-of-thought is enabled for models that support it.
    /// When null (default), the model or dialect default is used.
    /// </summary>
    public bool? EnableReasoning { get; set; }

    /// <summary>
    /// Default reasoning effort level for models that support it (e.g. "low", "medium", "high", "xhigh").
    /// </summary>
    public string? ReasoningEffort { get; set; }

    /// <summary>
    /// Explicit override for whether the active model supports reasoning.
    /// When null (default), determined by dialect or preset metadata.
    /// </summary>
    public bool? SupportsReasoning { get; set; }

    /// <summary>
    /// Explicit override for whether the active model supports reasoning effort tuning.
    /// When null (default), determined by dialect or preset metadata.
    /// </summary>
    public bool? SupportsReasoningEffort { get; set; }

    /// <summary>
    /// Maximum duration (in minutes) allowed for a local request before it is aborted.
    /// </summary>
    public int RequestTimeoutMinutes { get; set; } = 10;

    /// <summary>
    /// Optional delegate for application-specific normalization of parsed function calls.
    /// </summary>
    public FunctionCallNormalizer? FunctionCallNormalizer { get; set; }

    /// <summary>
    /// Controls whether verbose operation messages are emitted by this chat client.
    /// Defaults to false.
    /// </summary>
    public bool VerboseLogging { get; set; } = false;

    /// <summary>
    /// Optional per-chat-client <see cref="ILogger"/> instance for logging inference and model operations.
    /// Separate from the static native llama.cpp logger to avoid mixing logs between concurrent chats.
    /// </summary>
    public ILogger? Logger { get; set; }

    /// <summary>
    /// Optional <see cref="ILoggerFactory"/> used to create the per-chat-client logger when <see cref="Logger"/> is not specified.
    /// </summary>
    public ILoggerFactory? LoggerFactory { get; set; }
}